{{
(() => {
  const multiselectFields = [
    'sm', 'sn', 'sn_types', 'authors',
    'partners', 'protocol_types', 'protocols',
    'purposes', 'restrictions',
    'collections', 'file_formats', 'data_formats', 'instruments'
  ];
  const excludeFields = ['locations_stages', 'legacy_ref', 'created_at'];

  const normalizeValue = (val, key) => {
    if (val === null || val === undefined) return '';
    if (multiselectFields.includes(key) || Array.isArray(val)) {
      return (val || []).map(String).sort();
    }
    if (typeof val === 'number' || typeof val === 'boolean') return String(val);
    return val;
  };

  const normalize = (obj) => {
    const cleaned = _.omit(obj || {}, excludeFields);
    return _.mapValues(cleaned, (val, key) => normalizeValue(val, key));
  };

  const formData = JSONForm1.formData || {};
  const formNormalized = normalize(formData);
  const viewNormalized = normalize(appsmith.store.viewData);

  // Če forma polja ne pošlje, to ni sprememba
  ['status_code', 'primary_author', 'external'].forEach((key) => {
    if (!(key in formData)) {
      formNormalized[key] = viewNormalized[key] ?? '';
    }
  });

  const allKeys = _.union(_.keys(formNormalized), _.keys(viewNormalized));
  const diffs = allKeys
    .filter((key) => !_.isEqual(formNormalized[key], viewNormalized[key]))
    .map((key) => `- ${key}`);

  return diffs.length
    ? `Changed fields:\n${diffs.join('\n')}`
    : 'No changes detected.';
})()
}}
